sp_instance.widget_parameters:
{
	"html": {
		"value": "<style>
  .hod-navbar {
    width: 100%;
    background: linear-gradient(135deg, #0b2a4a 0%, #1a5276 100%);
    border-bottom-left-radius: 12px;
    border-bottom-right-radius: 12px;
    padding: 16px;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 8px;
    box-sizing: border-box;
    box-shadow: 0 4px 12px rgba(11, 42, 74, 0.2);
    margin-bottom: 16px;
  }

  .hod-navbar a {
    color: #e8f0fe;
    text-decoration: none;
    font-family: 'Segoe UI', system-ui, sans-serif;
    font-size: 15px;
    font-weight: 500;
    padding: 10px 22px;
    border-radius: 8px;
    transition: all 0.3s ease;
    background: rgba(255, 255, 255, 0.05);
    position: relative;
    overflow: hidden;
  }

  .hod-navbar a::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, #1d7ab3, #2a9fd8);
    border-radius: 8px;
    opacity: 0;
    transition: opacity 0.3s ease;
    z-index: -1;
  }

  .hod-navbar a:hover {
    background: rgba(255, 255, 255, 0.25);
    color: #ffffff;
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(29, 122, 179, 0.3);
  }

  .hod-navbar a:hover::before {
    opacity: 1;
  }

  .hod-navbar a.active {
    background: #1d7ab3;
    color: #ffffff;
    box-shadow: 0 2px 8px rgba(29, 122, 179, 0.3);
  }

  .hod-navbar a.active::before {
    opacity: 1;
    background: linear-gradient(135deg, #1d7ab3, #2389c4);
  }

  .hod-navbar a.active:hover {
    background: #2389c4;
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(29, 122, 179, 0.4);
  }
</style>
<nav class="hod-navbar"><a class="active" href="#"> 🏠 Home </a> <a href="#"> 🔔 Notifications </a> <a href="#"> ✅ Approved </a> <a href="#"> ❌ Rejected </a></nav>",
